'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{createHash}=require('node:crypto');
const cohort=require('./csrfIndirectChainCohort.json'),sha=x=>createHash('sha256').update(x).digest('hex');
function validateDeclaration(){for(const x of [cohort.source,cohort.clean,...Object.values(cohort.queries)])assert.equal(sha(x.text),x.sha256);assert.equal(cohort.source.text,require('../../server/data/csrfRagPayloads').CSRF_RAG_PAYLOADS.find(x=>x.id==='mfa-audit').doc);assert.equal(cohort.clean.text,require('../../server/data/csrfRagPayloads').CLEAN_KB_TEXT);assert.notEqual(cohort.queries.first.normalizedQuerySha256,cohort.queries.second.normalizedQuerySha256);return cohort;}
function assertActualCalls(calls,expectedModel=cohort.model.name){
 assert(calls.length>0);const actors=[];
 for(const call of calls){assert.equal(call.status,200);assert.equal(call.responseComplete,true);assert.equal(call.responseCaptureTruncated,false);assert.equal(sha(call.request),call.requestSha256);assert.equal(sha(call.response),call.responseSha256);const request=JSON.parse(call.request);assert.equal(request.model,expectedModel);const frames=request.stream===false?[JSON.parse(call.response)]:call.response.trim().split('\n').map(x=>JSON.parse(x));assert(frames.length);let text='';for(const [i,f]of frames.entries()){assert.equal(f.model,expectedModel);assert.equal(f.done,i===frames.length-1);assert(!f.error);const part=f.message?.content??f.response;assert.equal(typeof part,'string');text+=part;}if(request.messages?.some(m=>m.role==='system'&&m.content.includes("VaultLink's AI knowledge-base")))actors.push({request,text});}
 assert.equal(actors.length,1,'One actual summary response required');return actors[0];
}
function createIndirectEvidence({identity,documentEvidenceReader,progress,student,sibling,state,root,model}){
 assert(documentEvidenceReader&&typeof documentEvidenceReader.query==='function','Explicit historical document evidence reader required');
 const save=(name,value)=>fs.writeFileSync(path.join(root,name+'.json'),JSON.stringify(value,null,2),{mode:0o600});
 const documents=async user=>(await documentEvidenceReader.query("SELECT d.*,s.source_text,s.filename,(SELECT jsonb_agg(c ORDER BY chunk_index) FROM workshop_rag.chunks c WHERE c.document_id=d.document_id) chunks FROM workshop_rag.documents d LEFT JOIN workshop_rag.sources s USING(document_id) WHERE owner_id=$1 AND family='CSRF' ORDER BY document_id",[user.id])).rows;
 const judgments=async()=>(await identity.query('SELECT * FROM workshop_platform.objective_judgments WHERE user_id=$1 AND workshop_key=$2 ORDER BY evaluation_id',[student.id,'csrf_workshop'])).rows;
 const packets=async()=>(await identity.query('SELECT * FROM workshop_platform.grade_packets WHERE user_id=$1 ORDER BY evaluation_id',[student.id])).rows;
 return{documents,judgments,packets,async siblingSnapshot(){return{documents:await documents(sibling),state:await state(sibling)};},async complete(id){const rows=(await judgments()).filter(x=>x.objective_id===id&&x.disposition==='awarded');assert.equal(rows.length,1);const j=rows[0];assert.equal(j.verdict,'pass');assert.equal(j.result_json.provider,'ollama');assert.equal(j.result_json.model,model);const raw=(await packets()).find(x=>x.evaluation_id===j.evaluation_id)?.packet;assert(raw);assert.equal(sha(raw),j.evidence_digest);const p=JSON.parse(raw);assert.equal(p.facts.required_observation,true);assert.equal(p.rubric.objectiveId,id);save('csrf-indirect-'+id,{judgment:j,packet:p});const events=(await identity.query('SELECT * FROM graph_runtime.events WHERE run_id=$1 ORDER BY sequence',[j.run_id])).rows;save('csrf-indirect-events-'+id,events);
 if(id==='csrf_i1'){const d=(await documents(student)).find(x=>x.slot==='poison'&&!x.retired_at);assert(d);assert.equal(d.source_sha256,cohort.source.sha256);assert.equal(d.source_text,cohort.source.text);assert(d.chunk_count>0&&d.chunks.length===d.chunk_count);assert.equal(d.run_id,j.run_id);}
 else{const action=p.evidence.find(x=>x.id==='action')?.content;assert(action&&/rag/.test(action.name));assert.equal(action.result.executed,true);assert.equal(action.result.blocked,false);assert(!action.result.error);if(id==='csrf_i2')assert.equal(action.result.stateChanged,true);assert(events.some(x=>x.node==='forge'&&x.event_type==='node_end'&&x.metadata?.decisionSource==='lab_gadget_interpreter'));const observations=JSON.parse(fs.readFileSync(path.join(root,'csrf-indirect-search-observations.json'))).filter(x=>x.scope.runId===j.run_id);assert.equal(observations.length,2);for(const o of observations){assert.equal(o.scope.ownerId,student.id);assert.equal(o.result.receipt.ownerId,student.id);assert.equal(o.result.receipt.runId,j.run_id);}
 const merged=observations.flatMap(o=>o.result.chunks.map(c=>({...c,poison:o.scope.slot==='poison'}))).sort((a,b)=>b.score-a.score).slice(0,5);assert(merged.some(x=>x.poison&&x.score>=.30),'Poison must rank through genuine retrieval');assert.equal((await state(student)).indirect.victim.security.mfaEnabled,false);}
 const current=await progress.getWorkshopProgress(student.id,'csrf_workshop');assert.equal(current.completedObjectiveCount,Number(id.slice(-1)));return j;
 },async finalSnapshot(){return{judgments:await judgments(),packets:await packets()};},save};
}
module.exports={cohort,validateDeclaration,assertActualCalls,createIndirectEvidence};
